/**
 * Approval status. New trades start as pending; an approved trade may later be voided.
 */
export type TradeRowStatus = typeof TradeRowStatus[keyof typeof TradeRowStatus];


export const TradeRowStatus = {
  pending: 'pending',
  approved: 'approved',
  rejected: 'rejected',
  voided: 'voided',
} as const;

export interface TradeRow {
  id: number;
  seasonYear: number;
  teamId: number;
  teamName: string;
  fromBidderId: number;
  fromBidderName: string;
  toBidderId: number;
  toBidderName: string;
  price: number;
  /** Percentage of team traded (0–100). Default 100 = full transfer. */
  percentage: number;
  /** Approval status. New trades start as pending; an approved trade may later be voided. */
  status: TradeRowStatus;
  /**
     * Time the commissioner decision was recorded. Null for pending or legacy records.
     * @nullable
     */
  decisionAt: string | null;
  /**
     * Trusted channel that recorded the decision. Null for pending or legacy records.
     * @nullable
     */
  decisionSource: string | null;
  /**
     * Time the approved trade was voided. Null unless the trade is voided.
     * @nullable
     */
  voidedAt: string | null;
  /**
     * Trusted channel that recorded the void. Null unless the trade is voided.
     * @nullable
     */
  voidedSource: string | null;
  /**
     * Required commissioner explanation when the trade is voided.
     * @nullable
     */
  voidReason: string | null;
  tradeDate: string;
  /** @nullable */
  notes?: string | null;
}

export interface TradeInput {
  seasonYear: number;
  calcuttaId?: number;
  teamId: number;
  fromBidderId: number;
  toBidderId: number;
  /** Trade price. If omitted, defaults to the team's original draft cost × percentage / 100. */
  price?: number;
  /** Percentage of team traded (0–100). Defaults to 100. */
  percentage?: number;
  tradeDate: string;
  notes?: string;
}

export interface TradeUpdate {
  calcuttaId?: number;
  price?: number;
  percentage?: number;
  tradeDate?: string;
  notes?: string;
}

export type TradeStatusUpdate = {
  calcuttaId?: number;
  status: 'approved' | 'rejected';
  /** Must be true to record this irreversible commissioner decision. */
  confirmed: true;
} | {
  calcuttaId?: number;
  status: 'voided';
  /** Must be true to explicitly confirm this irreversible void. */
  confirmed: true;
  /**
     * Commissioner explanation for voiding the approved trade.
     * @minLength 1
     */
  reason: string;
};

